#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum DType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    Float32,
    Float64,
    Complex64,
    Complex128,
    Object,
}

impl DType {
    // Return the precedence value of the dtype as given in the problem
    fn precedence(&self) -> u8 {
        match self {
            DType::Bool => 0,
            DType::Int8 => 1,
            DType::Int16 => 2,
            DType::Int32 => 3,
            DType::Int64 => 4,
            DType::UInt8 => 5,
            DType::UInt16 => 6,
            DType::UInt32 => 7,
            DType::UInt64 => 8,
            DType::Float32 => 9,
            DType::Float64 => 10,
            DType::Complex64 => 11,
            DType::Complex128 => 12,
            DType::Object => 13,
        }
    }

    // Return the kind character associated with the dtype
    // Boolean: 'b', signed int: 'i', unsigned int: 'u', float: 'f',
    // complex: 'c', object: 'O'
    fn kind(&self) -> char {
        match self {
            DType::Bool => 'b',
            DType::Int8 | DType::Int16 | DType::Int32 | DType::Int64 => 'i',
            DType::UInt8 | DType::UInt16 | DType::UInt32 | DType::UInt64 => 'u',
            DType::Float32 | DType::Float64 => 'f',
            DType::Complex64 | DType::Complex128 => 'c',
            DType::Object => 'O',
        }
    }
}

fn find_max_precedence_type(types: Vec<DType>) -> DType {
    // The input vector is non-empty, so safe to unwrap max_by_key
    *types
        .iter()
        .max_by_key(|dt| dt.precedence())
        .expect("Non-empty vector guaranteed")
}

fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    let array_max = array_types.iter().max_by_key(|dt| dt.precedence());
    let scalar_max = scalar_types.iter().max_by_key(|dt| dt.precedence());

    match (array_max, scalar_max) {
        (None, None) => None, // both empty, no common type
        (Some(&a), None) => Some(a),
        (None, Some(&s)) => Some(s),
        (Some(&a), Some(&s)) => {
            if a.kind() == s.kind() {
                Some(a)
            } else {
                Some(s)
            }
        }
    }
}

